+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.contact.*;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.textfield.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @Test
+    void flow() {
+        navigate("contact", ContactView.class);
+        $(Button.class).withText("Send").single();
+        test($(TextField.class).withLabel("Name").single()).setValue("A");
+        $(Button.class).withText("Send").single().click();
+        assertTrue($(EmailField.class).single().isInvalid());
+        assertTrue($(TextArea.class).single().isInvalid());
+        test($(EmailField.class).single()).setValue("a@b.com");
+        test($(TextArea.class).single()).setValue("hi");
+        $(Button.class).withText("Send").single().click();
+        assertTrue($(TextField.class).withLabel("Name").single().isEmpty());
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        test($(TextField.class).withLabel("Name").single()).setValue("x");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+        try { navigate("about", AboutView.class); } catch (IllegalArgumentException ignored) { }
+        Button discard = $(Dialog.class).single().getFooter().getElement().getChildren()
+                .map(e -> e.getComponent().get()).map(c -> (Button) c)
+                .filter(b -> b.getText().equals("Discard")).findFirst().get();
+        discard.click();
+        assertEquals(1, $(com.vaadin.flow.component.html.H1.class).all().size());
+        assertEquals("About", $(com.vaadin.flow.component.html.H1.class).single().getText());
+    }
+}
